#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> ranges(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> ranges[i][j];
        }
    }

    vector<long long> starts, ends;
    for (const vector<long long>& r0 : ranges) { starts.push_back(r0[0]); ends.push_back(r0[1]); }
    sort(starts.begin(), starts.end());
    sort(ends.begin(), ends.end());
    long long disjoint = 0, p = 0;
    for (long long s : starts) {
        while (p < n && ends[p] < s) p++;
        disjoint += p;
    }
    cout << n * (n - 1) / 2 - disjoint << "\n";

    return 0;
}

